CREATE TABLE IF NOT EXISTS `rubric_comments` (`id` INT AUTO_INCREMENT PRIMARY KEY, `quest_id` INT NOT NULL, `owner_id` INT NOT NULL, `author_id` INT NOT NULL, `note` VARCHAR(500) NOT NULL, `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `topo_saves` (`id` INT AUTO_INCREMENT PRIMARY KEY, `user_id` INT NOT NULL, `name` VARCHAR(80) NOT NULL DEFAULT 'topologi', `payload` TEXT NOT NULL, `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `sponsors` (`id` INT AUTO_INCREMENT PRIMARY KEY, `name` VARCHAR(80) NOT NULL UNIQUE, `url` VARCHAR(255) NULL, `active` TINYINT NOT NULL DEFAULT 1, `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
